<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/pdo.php';
require_once __DIR__ . '/../config/reseller_integrations.php';
reseller_integrations_ensure_schema($pdo);
$chargeId=(int)($_GET['c']??0);$token=trim((string)($_GET['t']??''));
$st=$pdo->prepare('SELECT ch.*,c.name AS client_name,r.reseller_brand_name,r.name AS reseller_name,r.reseller_logo,r.reseller_primary_color,r.reseller_secondary_color FROM saas_reseller_customer_charges ch INNER JOIN companies c ON c.id=ch.client_company_id INNER JOIN companies r ON r.id=ch.reseller_company_id WHERE ch.id=? AND ch.public_token=? LIMIT 1');$st->execute([$chargeId,$token]);$ch=$st->fetch(PDO::FETCH_ASSOC)?:null;
if(!$ch){http_response_code(404);exit('Cobrança não encontrada.');}
$brand=trim((string)($ch['reseller_brand_name']??$ch['reseller_name']??'Revenda'))?:'Revenda';$logo=reseller_theme_logo_url($ch);$primary=reseller_integrations_color($ch['reseller_primary_color']??'','#0b1f5b');$secondary=reseller_integrations_color($ch['reseller_secondary_color']??'','#2454d6');
$qrSrc=trim((string)($ch['qr_image']??''));if($qrSrc!==''&&!str_starts_with($qrSrc,'data:')){$qrSrc='data:image/png;base64,'.$qrSrc;}
function pay_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagamento | <?=pay_h($brand)?></title><style>:root{--p:<?=$primary?>;--s:<?=$secondary?>}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:20px;font-family:Segoe UI,Arial;background:radial-gradient(circle at 90% 0,color-mix(in srgb,var(--s) 18%,transparent),transparent 35%),#f4f7fb;color:var(--p)}.card{width:min(620px,100%);background:#fff;border:1px solid #dce7f5;border-radius:28px;padding:25px;box-shadow:0 25px 70px rgba(11,31,91,.14)}.brand{display:flex;gap:12px;align-items:center}.brand img{width:70px;height:60px;object-fit:contain;border:1px solid #dce7f5;border-radius:17px;padding:6px}.value{font-size:38px;font-weight:950;margin:18px 0}.box{background:#f8fbff;border:1px solid #dce7f5;border-radius:18px;padding:14px;margin-top:12px}.qr{text-align:center}.qr img{max-width:280px;width:100%}textarea{width:100%;border:1px solid #bfd2f4;border-radius:13px;padding:11px}.btn{display:flex;justify-content:center;padding:13px;border-radius:999px;background:linear-gradient(135deg,var(--p),var(--s));color:#fff;font-weight:900;border:0;width:100%;cursor:pointer}.paid{background:#ecfdf5;color:#166534}</style></head><body><main class="card"><div class="brand"><img src="<?=pay_h($logo)?>"><div><strong><?=pay_h($brand)?></strong><div>Cobrança de <?=pay_h((string)$ch['client_name'])?></div></div></div><div class="value">R$ <?=number_format((float)$ch['amount'],2,',','.')?></div><div class="box"><strong><?=pay_h((string)$ch['description'])?></strong><div>Vencimento: <?=!empty($ch['due_date'])?(new DateTimeImmutable((string)$ch['due_date']))->format('d/m/Y'):'—'?></div></div><div id="statusBox" class="box <?=($ch['status']==='paid')?'paid':''?>">Status: <strong id="statusText"><?=pay_h((string)$ch['status'])?></strong></div><?php if($ch['status']!=='paid'):?><div class="box qr"><?php if($qrSrc!==''):?><img src="<?=pay_h($qrSrc)?>" alt="QR Code Pix"><?php endif;?></div><?php if(!empty($ch['pix_copy_paste'])):?><div class="box"><label>Pix copia e cola</label><textarea id="pix" rows="5" readonly><?=pay_h((string)$ch['pix_copy_paste'])?></textarea><button class="btn" type="button" onclick="navigator.clipboard.writeText(document.getElementById('pix').value)">Copiar código Pix</button></div><?php endif;?><?php endif;?></main><script>setInterval(async()=>{try{const r=await fetch('/revenda/pagamento_status.php?c=<?=$chargeId?>&t=<?=rawurlencode($token)?>');const j=await r.json();if(j.status){document.getElementById('statusText').textContent=j.status;if(j.status==='paid')location.reload();}}catch(e){}},8000);</script></body></html>
